import{Z as a,e as n,f as i,a0 as t}from"./chunks/framework.BBqb3frr.js";const m=JSON.parse('{"title":"Conditions and Validation","description":"","frontmatter":{},"headers":[],"relativePath":"browser/conditions-and-validation.md","filePath":"browser/conditions-and-validation.md","lastUpdated":1790490680000}'),o={name:"browser/conditions-and-validation.md"};function r(s,e,d,l,c,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="conditions-and-validation" tabindex="-1">Conditions and Validation <a class="header-anchor" href="#conditions-and-validation" aria-label="Permalink to &quot;Conditions and Validation&quot;">​</a></h1><p>All Formie browser packages share condition and validation rules through <code>@verbb/formie-core</code>. Use the <code>mode</code>, <code>effect</code> and <code>rules</code> definitions returned by Formie. Text comparisons use alphabetical order; numeric comparisons require a complete number; selected options match whole values. An invalid show rule keeps a field hidden, an invalid hide rule keeps it visible, and an invalid navigation rule prevents moving forward.</p><p>Server validation remains authoritative. Submit and page-transition results retain full nested errors such as <code>123.1.email</code>, rooted at the form-field instance ID. Render messages as plain text and focus the exact control. Derive page summaries from field errors and the current definition.</p><p>REST returns 422 validation, 409 stale state, 429 rate limits and 403 authorization. GraphQL submit and page mutations return expected domain failures in result data. A rejected page transition leaves the current page unchanged. Use the returned session when present.</p><p>Custom browser modules can add validation with <code>registerBrowserValidationRule(type, rule)</code> and remove it using the returned cleanup function. Formie supplies translated error messages and checks submissions again on the server, including rules the browser does not recognise.</p>',5)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
